'use strict';
const govPanel=document.createElement('section');govPanel.className='panel source-card';govPanel.innerHTML='<div class="section-title"><h2>Gov.kz</h2><span id="gov-status" class="badge"></span></div><p class="source-caption">Государственные структуры → Gov.kz</p><p>Сбор по проверенному списку до 500 учреждений. Контакты сохраняются сразу с назначением телефонов. Повтор списка — через 6 часов. Рассылки не запускаются.</p><details><summary>Карточки организаций</summary><label>Ссылки Gov.kz — по одной в строке<textarea id="gov-urls" rows="5" aria-label="Карточки Gov.kz" placeholder="https://www.gov.kz/org/kazyna"></textarea></label><p class="rule-text">Основные страницы /org/… или /org/…/contacts. Для изменения списка приостановите сбор. Сохранение списка начинает новый обход; существующие клиенты сохраняются.</p><button id="gov-save" class="outline">Сохранить список</button></details><div class="actions source-actions"><button id="gov-start" class="outline source-action-primary">Включить сбор</button><button id="gov-pause" class="outline">Пауза</button><button id="gov-refresh" class="outline">Обновить</button></div><p id="gov-worker" class="rule-text"></p><p id="gov-error" role="status"></p><p id="gov-summary" class="rule-text"></p><div id="gov-metrics" class="stats source-metrics"></div>';collectionPage.append(govPanel);
let govBusy=false,govLoaded=false;
async function refreshGov(){if(govBusy)return;govBusy=true;try{const s=await api('/api/gov');if(!govLoaded){document.getElementById('gov-urls').value=s.urls.join('\n');govLoaded=true;}document.getElementById('gov-status').textContent=s.enabled?(s.completed_at?'Ожидает следующего обхода':s.error?'Повтор / проверка ошибок':'Сбор включён'):'Приостановлен';document.getElementById('gov-status').className='badge '+(s.enabled?'green':'');document.getElementById('gov-start').disabled=s.enabled;document.getElementById('gov-pause').disabled=!s.enabled;for(const id of ['gov-save','gov-urls'])document.getElementById(id).disabled=s.enabled||s.busy;document.getElementById('gov-worker').textContent=(s.worker_alive?'Фоновый обработчик доступен.':'Фоновый обработчик не отвечает; запустите collect_gov.')+' Карточек пройдено: '+s.cursor+' / '+s.total+(s.next_attempt_at?' · Следующий запрос: '+new Date(s.next_attempt_at).toLocaleString('ru-RU',{timeZone:'Asia/Qyzylorda'}):'');document.getElementById('gov-error').textContent=s.error;const r=s.report;document.getElementById('gov-summary').textContent='За текущий обход: создано '+(r.created||0)+', дополнено '+(r.updated||0)+', без опубликованных контактов '+(r.without_contacts||0)+', ошибок карточек '+(r.failed||0)+'. Временные ошибки повторяются до трёх попыток. Карточки без опубликованных контактов отмечаются отдельно.';const metrics=document.getElementById('gov-metrics');metrics.replaceChildren();for(const [label,value]of [['Организаций',r.organizations],['Email',r.emails],['Телефонов',r.phones],['Обработано карточек',r.processed],['Без опубликованных контактов',r.without_contacts],['Ошибок карточек',r.failed]]){const article=document.createElement('article'),span=document.createElement('span'),strong=document.createElement('strong');span.textContent=label;strong.textContent=value||0;article.append(span,strong);metrics.append(article);}}catch(e){document.getElementById('gov-error').textContent=e.message;}finally{govBusy=false;}}
async function govAction(action){const payload={action};if(action==='configure')payload.urls=document.getElementById('gov-urls').value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);try{await api('/api/gov',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(action==='configure')govLoaded=false;await refreshGov();}catch(e){document.getElementById('gov-error').textContent=e.message;}}
document.getElementById('gov-start').onclick=()=>govAction('start');document.getElementById('gov-pause').onclick=()=>govAction('pause');document.getElementById('gov-save').onclick=()=>govAction('configure');document.getElementById('gov-refresh').onclick=refreshGov;collectionButton.addEventListener('click',refreshGov);setInterval(()=>{if(!collectionPage.hidden)refreshGov();},5000);
